using System.Diagnostics;
using System.Text.Json;
using AssetAccessManager.Domain;
using AssetAccessManager.Infrastructure;
using Microsoft.EntityFrameworkCore;
var s = Settings.Parse(args); await using var db = new AssetAccessDbContext(new DbContextOptionsBuilder<AssetAccessDbContext>().UseSqlServer(s.Connection).Options); await db.Database.MigrateAsync(); var existing = await db.Assets.CountAsync(); if (existing < s.Size) { var random = new Random(s.Seed); for (var offset = existing; offset < s.Size; offset += 500) { for (var i = offset; i < Math.Min(offset + 500, s.Size); i++) db.Assets.Add(Asset.RegisterSeed(Guid.NewGuid(), $"LT-{i:000000}", $"SN-{i:000000}", $"Model-{random.Next(1, 501):000}")); await db.SaveChangesAsync(); db.ChangeTracker.Clear(); } }
async Task<long> Search() { var timer = Stopwatch.StartNew(); _ = await db.Assets.AsNoTracking().Where(x => x.Model.Contains(s.Term) || x.AssetTag.Contains(s.Term) || x.SerialNumber.Contains(s.Term)).OrderBy(x => x.AssetTag).Take(25).Select(x => new { x.Id, x.AssetTag, x.Model, x.Status }).ToListAsync(); return timer.ElapsedMilliseconds; }
for (var i = 0; i < s.Warmups; i++) await Search(); var runs = new List<long>(); for (var i = 0; i < s.Runs; i++) runs.Add(await Search()); runs.Sort(); var output = new { s.Commit, Runtime = Environment.Version.ToString(), OS = Environment.OSVersion.ToString(), Architecture = System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture.ToString(), Environment.ProcessorCount, DatasetGenerator = "AssetAccessManager.Benchmarks/v1", s.Seed, DatasetSize = await db.Assets.CountAsync(), Concurrency = 1, Warmup = $"{s.Warmups} identical searches", MeasuredRuns = s.Runs, SearchTerm = s.Term, Baseline = new { RawMilliseconds = runs, MedianMilliseconds = runs[runs.Count / 2], P95Milliseconds = runs[(int)Math.Ceiling(runs.Count * .95) - 1] }, Optimization = "Not yet performed", OptimizedResult = (object?)null }; var json = JsonSerializer.Serialize(output, new JsonSerializerOptions { WriteIndented = true }); Console.WriteLine(json); if (s.Output is not null) await File.WriteAllTextAsync(s.Output, json);
file sealed record Settings(string Connection, string Commit, int Seed, int Size, int Warmups, int Runs, string Term, string? Output) { public static Settings Parse(string[] a) { string? Get(string n) { var i = Array.IndexOf(a, n); return i >= 0 && i + 1 < a.Length ? a[i + 1] : null; } return new(Get("--connection") ?? throw new ArgumentException("--connection required"), Get("--commit") ?? throw new ArgumentException("--commit required"), int.Parse(Get("--seed") ?? "1209"), int.Parse(Get("--size") ?? "25000"), int.Parse(Get("--warmups") ?? "2"), int.Parse(Get("--runs") ?? "10"), Get("--term") ?? "Model-250", Get("--output")); } }
